from docx import Document
from docx.shared import Pt, Cm, RGBColor
from docx.oxml.ns import qn

doc = Document()
for section in doc.sections:
    section.top_margin = Cm(2)
    section.bottom_margin = Cm(2)
    section.left_margin = Cm(2.5)
    section.right_margin = Cm(1.5)

normal = doc.styles['Normal']
normal.font.name = 'Arial'
normal.font.size = Pt(12)
normal._element.rPr.rFonts.set(qn('w:eastAsia'), 'Arial')
normal.paragraph_format.line_spacing = 1.5
normal.paragraph_format.space_after = Pt(6)

for hname, size in [('Heading 1', 14), ('Heading 2', 12)]:
    st = doc.styles[hname]
    st.font.name = 'Arial'
    st.font.size = Pt(size)
    st.font.bold = True
    st.font.color.rgb = RGBColor(0, 0, 0)
    st.paragraph_format.line_spacing = 1.5
    st.paragraph_format.space_before = Pt(8)
    st.paragraph_format.space_after = Pt(4)

def h1(t): doc.add_heading(t, level=1)
def h2(t): doc.add_heading(t, level=2)
def p(t, style=None): doc.add_paragraph(t, style=style)
def b(t): p(t, style='List Bullet')

h1('ДЗ 6. Пакет запуска и решение по результатам A/B-теста (вариант 2)')

h1('Часть 1. Пакет запуска')

h2('1. Стратегический контекст')
p('TechGourmet – приложение доставки еды, продукту 3 месяца, ~1200 регистраций в неделю, приток стабилен. Режим – захват рынка / блиц-рост: цель – растить базу, а не прибыль, поэтому primary – активация. Цепочка к бизнес-цели: конверсия регистрация -> первый заказ за 7 дней (primary) -> число платящих клиентов и их LTV (драйвер) -> рост выручки и валовой прибыли (бизнес-цель): при стабильном притоке рост конверсии почти линейно увеличивает платящих клиентов. Порог успеха +20% (12.0% -> 14.4%) – верхняя граница бизнес-требования 15-20%, тогда Go окупается при любой оценке затрат. В режиме «прибыльность» primary стала бы маржой на заказ, конверсия ушла бы в guardrails, добавились бы holdout и дата переоценки.')

h2('2. Анализ воронки и гипотеза')
p('Точки оттока в воронке регистрация -> первый заказ: (1) 35% не добавляют адрес доставки – Setup-момент, без него заказ невозможен, самая острая точка; (2) 40% не заполняют профиль – растягивают Time-to-Value (сейчас 3-4 дня); (3) экран приветствия не ведет к ценности. Из трех идей (автоопределение геолокации на экране адреса; перенос профиля после первого заказа; редизайн приветствия) выбираю первую: она бьет в самую массовую измеренную точку оттока, механика уже есть в экране, причинная цепочка короткая.')
p('Гипотеза: если на экране ввода адреса сделать автоопределение геолокации основным сценарием (адрес предзаполнен, пользователь только подтверждает), то доля добавивших адрес вырастет, потому что снизятся трудозатраты Setup-момента, что приведет к росту конверсии в первый заказ за 7 дней с 12.0% до 14.4% и выше, потому что адрес – обязательный шаг перед заказом, и его прохождение сокращает Time-to-Value: пользователь успевает заказать «на сегодня вечером».')

h2('3. Индикаторы')
p('Primary (одна): конверсия регистрация -> первый заказ за 7 дней = заказы за 168 ч / все новые пользователи, включенные в эксперимент (база 12.0%, порог +20% при p < 0.05, двусторонний критерий, мощность 80%).')
p('Secondary (проверяют механизм): конверсия экрана адреса в «адрес добавлен» (сейчас ~65%); доля добавивших адрес за 7 дней; медианное время регистрация -> заказ (сейчас 3-4 дня); доля заполнивших профиль (~60% – контроль изоляции, измениться не должна).')
p('Guardrails:')
b('отмененные первые заказы / все первые заказы группы (~5%), лимит +1 п. п. к контролю – риск «мусорных» заказов из-за неверно определенного адреса (обязательный guardrail компании);')
b('второй заказ за 14 дней – не хуже контроля на 0.5 п. п. – риск «мертвого роста»; оценивается по первым заказам, случившимся не позднее чем за 14 дней до даты решения;')
b('crash-free rate экрана адреса – падение не более 0.2 п. п. – технический риск геолокации;')
b('обращения в поддержку по первому заказу – рост не более 20% к контролю – риск плохого опыта;')
b('закрытие приложения на экране адреса в первую сессию – рост не более 2 п. п. – риск отпугивания запросом геолокации.')

h2('4. Чувствительность и выборка')
p('Расчет на калькуляторе AB Testguide (α = 5%, мощность 80%, двусторонний, база 12.0%, ~600 пользователей в неделю на группу): под MDE +20% нужно 3121 пользователь на группу (5.2 недели), под +15% – 5443 (9.1 недели). Порог +20% достижим за окно 6 недель, +15% недостижим за разумный срок, фиксирую MDE = +20% – это осознанный выбор, а не подгонка: эффект меньше 20% все равно не окупал бы затраты; цена выбора – эффект +15…+20% попадет в серую зону.')

h2('5. Дизайн и окно наблюдения')
p('Контроль видит текущий экран ввода адреса, тест – версию с автоопределением геолокации и предзаполненным адресом. Сплит 50/50 – при ограниченном трафике равные группы дают максимум мощности. Единица рандомизации – user_id, сплит фиксируется в профиле; попадание в эксперимент – регистрация, экспозиция – первый показ экрана адреса. Окно – 6 недель (42 дня, кратно неделе): набор идет 5 недель, 6-я неделя – дозревание 7-дневной конверсии последней когорты (3000 на группу, мощность ~78% вместо 80% – осознанная цена за дозревание); первые 7 дней – адаптация без промежуточных решений, значимость проверяем один раз в конце. Дата решения – понедельник седьмой недели.')

h2('6. MVA и здоровье данных')
p('События (трекинг-план тестируется до запуска): experiment_assignment, address_screen_view, geolocation_prompt_result, address_input_method, address_confirmed, profile_completed, order_created, order_cancelled, app_crash, support_ticket_created, app_exit. SRM-мониторинг: ежедневный хи-квадрат против 50/50, алерт при p < 0.01; при SRM результат не интерпретируется – исход Invalid, исправление и перезапуск. Зафиксированные разрезы: платформа (мобайл / десктоп), возраст (25-40 против прочих), неделя входа в тест.')

h2('7. Правила решений')
p('Порядок применения: здоровье (Invalid) -> Kill -> guardrails (Adapt) -> primary через CI (Go / серая зона / Stop).')

rows = [
    ('Исход измерения', 'Решение', 'Действие'),
    ('95% CI эффекта полностью выше +20%, guardrails в норме', 'Go', 'Раскатка 25% -> 50% -> 100% с мониторингом guardrails, holdout 5%, переоценка через квартал'),
    ('Точечная оценка >= +20%, но отмены > контроль + 1 п. п.', 'Adapt', 'Не раскатываем; ищем механизм деградации, дорабатываем, перезапускаем'),
    ('95% CI включает +20% (при любой точечной оценке)', 'Серая зона', 'Одно продление на 2 недели, ровно один раз; затем Stop, если CI не сузился'),
    ('95% CI полностью ниже +20%', 'Stop', 'Выключаем, разбираем модель, фиксируем в реестре'),
    ('SRM, дыры в логах, критический инцидент', 'Invalid', 'Не интерпретируем, чиним, перезапускаем; дата решения сдвигается'),
    ('Отмены > контроль + 3 п. п. в любой момент', 'Kill', 'Немедленное выключение, не дожидаясь конца окна'),
]
t = doc.add_table(rows=len(rows), cols=3)
t.style = 'Table Grid'
for i, row in enumerate(rows):
    for j, cell in enumerate(row):
        c = t.rows[i].cells[j]
        c.text = cell
        for par in c.paragraphs:
            par.paragraph_format.line_spacing = 1.15
            par.paragraph_format.space_after = Pt(2)
            for run in par.runs:
                run.font.name = 'Arial'
                run.font.size = Pt(11)
                if i == 0:
                    run.bold = True
p('Владелец решения один – продакт-менеджер онбординга; анализ готовит аналитик, эскалация к CPO – только для серой зоны; решение фиксируется в реестре экспериментов.')

h1('Часть 2. Решение по данным теста')

h2('1. Здоровье теста')
p('По дизайну в расчет primary входят созревшие когорты дней 1-35: A – 2973, B – 3034 пользователя (дни 36-42 использую как контрольный разрез). SRM: χ² = (2973 - 3003.5)²/3003.5 + (3034 - 3003.5)²/3003.5 = 0.62, p = 0.43 при пороге алерта p < 0.01 – отклонения нет, сплит корректен; на полных 42 днях (3568/3588) вывод тот же. Окно 42 дня = 6 полных недель, кратность соблюдена, конверсия в данных созревшая, выборка соответствует плану. Вывод: тест здоров, результаты пригодны для решения. Ограничения выгрузки: знаменатель – пользователи с экспозицией, а не все включенные (группы сопоставимы, сравнение валидно); guardrails 2-5 в данных нет, проверяю только обязательный guardrail по отменам.')

h2('2. Результат теста')
p('Primary: A = 372 / 2973 = 12.51%, B = 488 / 3034 = 16.08%; абсолютная разница +3.57 п. п., относительная +28.5%. z-критерий для двух долей: p_объед = (372 + 488) / 6007 = 14.32%, z = 3.95, p = 0.00008 < 0.05 – эффект значим. 95% CI разности: [+1.80; +5.34] п. п., в относительных [+14.4%; +42.7%] – интервал включает порог +20%.')
p('Guardrail по отменам: A = 21 / 372 = 5.65%, B = 36 / 488 = 7.38%, разница +1.73 п. п. > лимита +1 п. п. – guardrail нарушен (разница незначима, z = 1.01, p = 0.31, но правило пакета пороговое). Kill-порог +3 п. п. не достигнут: ежедневная кумулятивная доля отмен превышала +3 п. п. только в день 1 (по 1 отмене в группах – шум), далее колебалась от -4.2 до +2.9 п. п. Контроль на полных 42 днях: +24.3%, отмены +2.36 п. п. – картина та же. Проверка по закону Тваймана: всплеск дня 20 в тесте (28.4% при средних ~16%) исключала – рост сохраняется (+25.4%); по неделям тест выше контроля во всех пяти неделях (+2.3…+4.4 п. п.) – эффект стабилен, не новизна.')

h2('3. Решение: Adapt')
p('Применяю таблицу в зафиксированном порядке. Тест здоров, Kill не достигнут. Guardrail по отменам нарушен: +1.73 п. п. при лимите +1 п. п. (на полных данных +2.36 п. п. – вплотную к Kill-зоне, раскатка невозможна). Primary выросла до 16.08% (+28.5%): p = 0.00008 подтверждает наличие эффекта, а CI показывает, что размер порядка +20% и выше статистически непротиворечив. Это в точности строка Adapt моей таблицы: primary пройден, но обязательный guardrail нарушен (без нарушения была бы серая зона – CI включает +20%, – но guardrails проверяются раньше primary). Раскатывать нельзя: компания прямо не считает заказы, купленные ценой отмен, успехом. Дальше: разбираем механизм роста отмен (версия – неточно определенный адрес, заказ уезжает «не туда»), дорабатываем подтверждение адреса (подсветка на карте, явное подтверждение дома) и перезапускаем тест; день 20 проверяем отдельно.')

h2('4. Оценка качества собственного пакета')
p('Главный урок: уязвимыми оказались формулировки метрик, а не расчеты. Зафиксированный базис guardrail по отменам («отмененные первые заказы / все первые заказы группы») спас анализ: без него те же данные читались бы двусмысленно (7.38% против 5.65% в базисе заказов или 1.19% против 0.71% в базисе экспозиций). До запуска изменила бы три вещи. Первое: primary определила бы как конверсию в неотмененный первый заказ – сейчас отмененные засчитываются как успех, а чистит их guardrail; пересчет (11.81% -> 14.90%, +26.2%) вывод не меняет, но метрика сама отражала бы то, что компания считает успехом. Второе: пороги guardrails экспертные, без проверки чувствительности – у guardrail 1 разница +1.73 п. п. при 21 и 36 отменах незначима (p = 0.31), порог +1 п. п. срабатывает на шуме почти так же легко, как на реальном эффекте. Третье: Kill-правилу не хватало защиты от малых выборок – в день 1 оно формально сработало бы на единичных отменах. Также знаменатель primary из пакета (все включенные) расходится с выгрузкой по экспозициям – срез данных стоило согласовать с аналитиками до запуска.')

out = '/Users/szime/git/study/стратегия продукта/дз 6/ДЗ 6_Зименкова Софья_М08-502_Отчет.docx'
doc.save(out)
words = sum(len(par.text.split()) for par in doc.paragraphs) + sum(len(c.text.split()) for tb in doc.tables for r in tb.rows for c in r.cells)
print('saved:', out)
print(f'слов: {words}, оценка страниц: {words/400:.1f}-{words/350:.1f}')
